namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language arts." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilization." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Prof. James Martinez", InstructorBio = "Prof. Martinez specializes in algorithm optimization and competitive programming. He is a two-time ACM ICPC World Finals judge.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Principles of database design, SQL, normalization, transaction processing, and modern NoSQL approaches.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Anika Patel", InstructorBio = "Dr. Patel spent a decade at Oracle before joining academia. Her research focuses on distributed database systems.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications to science and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with a passion for making calculus accessible. He has authored three textbooks on introductory mathematics.", DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 5, Code = "MATH 220", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Prof. Elena Volkov", InstructorBio = "Prof. Volkov's research spans algebraic geometry and applied linear algebra. She collaborates with the CS department on machine learning projects.", DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 6, Code = "ENG 101", Title = "Composition and Rhetoric", Description = "Develop critical reading and writing skills through analysis of diverse texts and composition of argumentative essays.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Okafor", InstructorBio = "Prof. Okafor is a published novelist and essayist whose work explores themes of identity and language. He has taught writing workshops internationally.", DepartmentId = 3, DepartmentCode = "ENG", DepartmentName = "English", IsFeatured = false },
            new() { Id = 7, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, including poetry, fiction, and nonfiction.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Maria Santos", InstructorBio = "Dr. Santos specializes in 20th-century American fiction and has published two books on the Harlem Renaissance.", DepartmentId = 3, DepartmentCode = "ENG", DepartmentName = "English", IsFeatured = true },
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 3:00–5:00 PM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright is an experimental physicist who previously worked at CERN. He brings real-world particle physics experience to undergraduate education.", DepartmentId = 4, DepartmentCode = "PHYS", DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 9, Code = "PHYS 240", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM + Fri Lab 2:00–4:00 PM", InstructorName = "Prof. Lisa Nakamura", InstructorBio = "Prof. Nakamura's research in photonics has earned multiple NSF grants. She is passionate about increasing diversity in physics.", DepartmentId = 4, DepartmentCode = "PHYS", DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 10, Code = "HIST 101", Title = "World Civilizations", Description = "Survey of major world civilizations from ancient Mesopotamia to the modern era, exploring cultural, political, and economic developments.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Dr. Ahmed Hassan", InstructorBio = "Dr. Hassan is an archaeologist and historian whose fieldwork in the Middle East has uncovered new insights into early urban societies.", DepartmentId = 5, DepartmentCode = "HIST", DepartmentName = "History", IsFeatured = true },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

