 @page "/enroll"
 @using UniversityCourseCatalog.Models
 @using UniversityCourseCatalog.Services
 @inject CatalogService CatalogService

 <PageTitle>Enrollment Request - University Course Catalog</PageTitle>

 <div class="container">
     <h1 class="my-4">Enrollment Request</h1>

     @if (submitted)
     {
         <div class="alert alert-success">
             <h4>Request Submitted</h4>
             <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@selectedCourseTitle</strong> has been received.</p>
             <a href="/courses" class="btn btn-primary mt-2">Browse More Courses</a>
         </div>
     }
     else
     {
         <p>Fill out the form below to request enrollment in a course.</p>

         <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm">
             <DataAnnotationsValidator />

             <div class="mb-3">
                 <label for="studentName" class="form-label">Full Name</label>
                 <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" required />
             </div>

             <div class="mb-3">
                 <label for="studentId" class="form-label">Student ID</label>
                 <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" required />
             </div>

             <div class="mb-3">
                 <label for="courseId" class="form-label">Course</label>
                 <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                     <option value="0">-- Select a course --</option>
                     @foreach (var course in courses)
                     {
                         <option value="@course.Id">@course.Code - @course.Title</option>
                     }
                 </InputSelect>
             </div>

             <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
         </EditForm>
     }
 </div>

 @code {
     [SupplyParameterFromForm]
     private EnrollmentRequest? Model { get; set; }

     protected override void OnInitialized()
     {
         Model ??= new();
         courses = CatalogService.GetCourses();

         if (CourseId.HasValue && Model.CourseId == 0)
         {
             Model.CourseId = CourseId.Value;
         }
     }

     [SupplyParameterFromQuery]
     private int? CourseId { get; set; }

     private List<Course> courses = new();
     private bool submitted;
     private string selectedCourseTitle = string.Empty;

     private void HandleSubmit()
     {
         if (string.IsNullOrWhiteSpace(Model.StudentName) || string.IsNullOrWhiteSpace(Model.StudentId) || Model.CourseId == 0)
             return;

         selectedCourseTitle = courses.FirstOrDefault(c => c.Id == Model.CourseId)?.Title ?? "Unknown";
         CatalogService.SubmitEnrollment(Model);
         submitted = true;
     }
 }

